<?php $pageTitle='Review faculty import';$error=app()->session()->pullFlash('error'); ?>
<section class="page-heading"><div><p class="eyebrow">Validation preview</p><h1>Review faculty import</h1><p><?= e($batch['original_filename']) ?> contains <?= number_format((int)$batch['total_rows']) ?> rows.</p></div><a class="secondary-button" href="<?= e(url('faculty/import')) ?>">Upload another</a></section>
<?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
<section class="import-summary"><article><span>Ready</span><strong><?= (int)$batch['valid_rows'] ?></strong></article><article><span>Invalid</span><strong><?= (int)$batch['invalid_rows'] ?></strong></article><article><span>Status</span><strong><?= e(ucfirst($batch['status'])) ?></strong></article></section>
<section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Row</th><th>Employee ID</th><th>Name</th><th>School</th><th>Designation</th><th>Validation</th><th>Messages</th></tr></thead><tbody><?php foreach($rows as $row):$s=json_decode($row['source_data'],true);$messages=json_decode($row['validation_messages'],true)?:[];?><tr><td><?= (int)$row['row_number'] ?></td><td><strong><?= e($s['employee_id']??'') ?></strong></td><td><?= e($s['name']??'') ?></td><td><?= e($s['school_code']??'') ?></td><td><?= e($s['designation']??'') ?></td><td><span class="status-label <?= e($row['validation_status']) ?>"><?= e(ucfirst($row['validation_status'])) ?></span></td><td><?= e(implode(' ',$messages)?:'Ready to import') ?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($batch['status']==='review'):?><form method="post" action="<?= e(url('faculty/import/'.$batch['id'].'/commit')) ?>" class="commit-bar"><?= csrf_field() ?><p><strong>Commit valid rows?</strong><span>Invalid rows remain available in this report.</span></p><button class="primary-button" type="submit" <?= (int)$batch['valid_rows']===0?'disabled':'' ?>>Import <?= (int)$batch['valid_rows'] ?> faculty</button></form><?php endif;?>
